runner_admission.body:
name: organization runner admission

on:
  workflow_call:
    inputs:
      runs_on:
        type: string
        required: false
        default: '["ubuntu-latest"]'
    outputs:
      runs_on:
        value: ${{ jobs.admission.outputs.runs_on }}
      native_authorized:
        value: ${{ jobs.admission.outputs.native_authorized }}
      reason:
        value: ${{ jobs.admission.outputs.reason }}

jobs:
  admission:
    runs-on: ubuntu-latest
    permissions: {}
    timeout-minutes: 2
    outputs:
      runs_on: ${{ steps.select.outputs.runs_on }}
      native_authorized: ${{ steps.select.outputs.native_authorized }}
      reason: ${{ steps.select.outputs.reason }}
    steps:
      # No checkout, API credential, secret inheritance or caller-script execution.
      # Private/unavailable membership is UNKNOWN and receives hosted CI.
      - id: select
        name: Select a runner from original event identity
        env:
          REPOSITORY: ${{ github.repository }}
          ORIGINAL_ACTOR: ${{ github.actor }}
          ORIGINAL_ACTOR_ID: ${{ github.actor_id }}
          TRIGGERING_ACTOR: ${{ github.triggering_actor }}
          EVENT_NAME: ${{ github.event_name }}
          PR_AUTHOR: ${{ github.event.pull_request.user.login }}
          PR_AUTHOR_ID: ${{ github.event.pull_request.user.id }}
          HEAD_REPOSITORY: ${{ github.event.pull_request.head.repo.full_name }}
          REQUESTED_RUNS_ON: ${{ inputs.runs_on }}
        run: |
          node <<'NODE'
          const fs = require('node:fs');
          const hosted = ['ubuntu-latest'];
          // Add a developer only after the operator trusts them. Numeric GitHub
          // account IDs do not change when a login is renamed.
          const trustedActorIds = new Set(['42527473']);
          const write = (runsOn, authorized, reason) => {
            fs.appendFileSync(process.env.GITHUB_OUTPUT,
              `runs_on=${JSON.stringify(runsOn)}\nnative_authorized=${authorized}\nreason=${reason}\n`);
          };
          write(hosted, false, 'membership-not-confirmed');
          async function select() {
            const env = process.env;
            if (!/^scitex-ai\/[A-Za-z0-9_.-]+$/i.test(env.REPOSITORY || '')) return;
            if (!['push', 'pull_request', 'schedule', 'workflow_dispatch'].includes(env.EVENT_NAME)) return;
            const login = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?$/;
            if (!login.test(env.ORIGINAL_ACTOR || '') ||
                env.ORIGINAL_ACTOR.toLowerCase() !== (env.TRIGGERING_ACTOR || '').toLowerCase() ||
                !/^\d+$/.test(env.ORIGINAL_ACTOR_ID || '') ||
                !trustedActorIds.has(env.ORIGINAL_ACTOR_ID)) {
              write(hosted, false, 'actor-not-allowlisted');
              return;
            }
            if (env.EVENT_NAME === 'pull_request') {
              if (!env.HEAD_REPOSITORY || env.HEAD_REPOSITORY.toLowerCase() !== env.REPOSITORY.toLowerCase()) {
                write(hosted, false, 'fork-or-missing-origin');
                return;
              }
              if (!login.test(env.PR_AUTHOR || '') ||
                  env.PR_AUTHOR.toLowerCase() !== env.ORIGINAL_ACTOR.toLowerCase() ||
                  !/^\d+$/.test(env.PR_AUTHOR_ID || '') ||
                  !trustedActorIds.has(env.PR_AUTHOR_ID)) {
                write(hosted, false, 'pr-author-not-allowlisted');
                return;
              }
            }
            let requested;
            try { requested = JSON.parse(env.REQUESTED_RUNS_ON || ''); } catch { return; }
            if (typeof requested === 'string') requested = [requested];
            if (!Array.isArray(requested) || !requested.length || requested.length > 12 ||
                requested.some(s => typeof s !== 'string' || s.length > 80)) return;
            const native = requested.includes('self-hosted');
            const known = new Set(['self-hosted', 'Linux', 'X64', 'scitex-ci', 'scitex-org-cpu',
              'scitex-local-cpu', 'scitex-docker', 'sac-control-plane',
              'scitex-compute-02', 'scitex-compute-03', 'scitex-compute-04']);
            if (native && (requested.some(s => !known.has(s)) ||
                !requested.some(s => ['scitex-ci', 'scitex-org-cpu', 'scitex-local-cpu', 'scitex-docker'].includes(s)))) {
              write(hosted, false, 'undeclared-native-destination');
              return;
            }
            if (!native && requested.some(s => !/^(ubuntu|windows|macos)-(latest|[0-9]+(?:\.[0-9]+)?(?:-arm64)?)$/.test(s))) return;
            // The selected reusable workflow is the server-side boundary.
            // Its fixed actor allowlist admits trusted same-repo work while
            // fork PRs and all other actors stay on GitHub-hosted runners.
            write(native ? {group: 'Organization', labels: requested} : requested,
              native, native ? 'trusted-actor' : 'requested-hosted');
          }
          select().catch(() => { /* Fixed hosted outputs already exist; fail closed. */ });
          NODE
